#include <iostream>
#include <string>
#include <regex>
#include <algorithm>

int main() {
    int length;
    std::cin >> length;
    std::string str;
    std::cin >> str;

    std::regex pattern("\\([a-zA-Z_]*\\)");
    std::string replacedStr = std::regex_replace(str, pattern, "_");

    size_t maxPartLength = 0;
    size_t start = 0;
    size_t pos;
    while ((pos = replacedStr.find('_', start)) != std::string::npos) {
        maxPartLength = std::max(maxPartLength, pos - start);
        start = pos + 1;
    }
    maxPartLength = std::max(maxPartLength, replacedStr.length() - start);
    std::cout << maxPartLength << std::endl;

    int totalCount = 0;
    bool inside = false;
    int startIdx = -1, endIdx = -1;
    for (int i = 0; i < (int)str.length(); ++i) {
        char c = str[i];
        if (c == '(') {
            inside = true;
            startIdx = i;
        } else if (c == ')' && inside) {
            inside = false;
            endIdx = i;
            std::string insideStr = str.substr(startIdx + 1, endIdx - startIdx - 1);
            if (!insideStr.empty()) {
                size_t countParts = 0;
                size_t innerStart = 0;
                size_t innerPos;
                while ((innerPos = insideStr.find('_', innerStart)) != std::string::npos) {
                    countParts++;
                    innerStart = innerPos + 1;
                }
                // If the inside string does not start with '_', add 1 for the last segment
                if (!insideStr.empty() && insideStr[0] != '_') {
                    countParts++;
                } else if (!insideStr.empty() && insideStr[0] == '_') {
                    // Subtract 1 if the first character is '_', as per original logic
                    countParts = countParts > 0 ? countParts - 1 : 0;
                }
                totalCount += countParts;
            }
        }
    }
    std::cout << totalCount << std::endl;
    return 0;
}
